import{_ as o,o as t,c as a,a as i}from"./app.CYXXef1p.js";const m=JSON.parse('{"title":"ADR-016: Two Python Surfaces (Core Runtime vs Tooling/Test)","description":"","frontmatter":{},"headers":[],"relativePath":"reference/ADR-016-two-python-surfaces.md","filePath":"reference/ADR-016-two-python-surfaces.md","lastUpdated":1771678191000}'),s={name:"reference/ADR-016-two-python-surfaces.md"};function r(n,e,l,c,d,u){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-016-two-python-surfaces-core-runtime-vs-tooling-test" tabindex="-1">ADR-016: Two Python Surfaces (Core Runtime vs Tooling/Test) <a class="header-anchor" href="#adr-016-two-python-surfaces-core-runtime-vs-tooling-test" aria-label="Permalink to &quot;ADR-016: Two Python Surfaces (Core Runtime vs Tooling/Test)&quot;">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>ACCEPTED (2026-02-21)</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>WL-120 and WL-136 identified sustained Python growth in mixed-purpose modules. Runtime command paths and tooling/test/research helpers were co-located, which increased coupling, slowed default quality lanes, and made decomposition progress hard to measure.</p><p>The repository already introduced extraction modules (<code>dag_impl.py</code>, <code>work_stream_impl.py</code>, <code>observability_impl.py</code>, <code>cli_dag.py</code>) and a boundary checker (<code>scripts/check_thegent_core_boundary.py</code>), but the architecture decision itself was not ratified in ADR form.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Adopt and enforce two explicit Python surfaces:</p><ol><li>Core runtime surface:</li></ol><ul><li>Includes runtime command handlers and runtime execution/control modules.</li><li>Must trend downward in LOC and import complexity.</li><li>Must stay on fast-lane validation paths.</li></ul><ol start="2"><li>Tooling/test/research surface:</li></ol><ul><li>Includes tests, scripts, docs generators, migration/diagnostic tooling.</li><li>May grow independently, but must not become a runtime dependency without explicit approval.</li><li>Runs in separate/deeper lanes where possible.</li></ul><p>Routing rule:</p><ul><li>When a domain has an extracted implementation module, command surfaces import that module directly instead of pulling handlers from <code>impl.py</code>.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p>Positive:</p><ul><li>Clear ownership and enforcement target for WL-136.</li><li>Lower coupling between command surfaces and the legacy <code>impl.py</code> monolith.</li><li>Better decomposition signal for WL-120 progress.</li></ul><p>Tradeoffs:</p><ul><li>Transition period keeps some compatibility exports in <code>impl.py</code>.</li><li>Additional import-routing checks are required to prevent regressions.</li></ul><h2 id="implementation-notes-track-a-closeout-slice" tabindex="-1">Implementation Notes (Track A closeout slice) <a class="header-anchor" href="#implementation-notes-track-a-closeout-slice" aria-label="Permalink to &quot;Implementation Notes (Track A closeout slice)&quot;">​</a></h2><ul><li><code>src/thegent/cli/commands/plan_cmds.py</code> routes <code>dag_status_impl</code> via <code>dag_impl</code>, and routes work-stream actions via <code>work_stream_impl</code>.</li><li><code>src/thegent/cli/commands/cli_dag.py</code> routes <code>dag_status_impl</code> via <code>dag_impl</code>.</li><li>Focused regression test added: <ul><li><code>tests/commands/test_wl120_extraction_import_routing.py</code></li></ul></li></ul><h2 id="related-artifacts" tabindex="-1">Related Artifacts <a class="header-anchor" href="#related-artifacts" aria-label="Permalink to &quot;Related Artifacts&quot;">​</a></h2><ul><li><code>docs/plans/WL-136-TWO-PYTHON-SURFACES.md</code></li><li><code>docs/plans/2026-02-21-MODERNIZATION-MASTER-PLAN.md</code></li><li><code>scripts/check_thegent_core_boundary.py</code></li><li><code>config/thegent_core_boundary.toml</code></li></ul>',23)])])}const h=o(s,[["render",r]]);export{m as __pageData,h as default};
